#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 1005

int grid[MAXN][MAXN]; // 2D difference array for the triangular grid

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    // Process each rubber band
    for (int i = 0; i < M; i++) {
        int a, b, x;
        scanf("%d %d %d", &a, &b, &x);

        // Add 1 to all points inside the triangle (a,b), (a+x,b), (a+x,b+x)
        // Using difference array technique for triangular region
        grid[a][b] += 1;
        if (a + x <= N) {
            grid[a + x][b] -= 1;
            if (b + x <= a + x) {
                grid[a + x][b + x] += 1;
            }
        }
    }

    // Propagate differences to get actual counts
    // For each row from top to bottom
    for (int i = 1; i <= N; i++) {
        // Propagate horizontally within row
        for (int j = 1; j <= i; j++) {
            if (j > 1) {
                grid[i][j] += grid[i][j-1];
            }
        }
        // Propagate diagonally to next row (like Pascal's triangle)
        if (i < N) {
            for (int j = 1; j <= i; j++) {
                grid[i+1][j] += grid[i][j];
                grid[i+1][j+1] += grid[i][j];
                grid[i+1][j] -= grid[i][j]; // subtract from left neighbor to avoid double count
            }
        }
    }

    // Count nails enclosed by at least one rubber band
    int count = 0;
    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= i; j++) {
            if (grid[i][j] > 0) {
                count++;
            }
        }
    }

    printf("%d\n", count);

    return 0;
}

