#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    // Using 2D imos on triangular coordinates.
    // For a triangle T(a,b,x): all enclosed nails are
    // {(i,j) | a <= i <= a+x, b <= j <= b + (i-a)}
    //
    // Let d = i-a. Then on row i, covered interval is [b, b+d].
    // This can be represented as:
    // count(i,j) = prefA(i,j) - prefB(i,j)
    // with updates on two triangular-prefix structures.
    //
    // We maintain arrays on coordinates (r,c), 1<=c<=r<=N.
    // After accumulation:
    // S[r][c] = val[r][c] + S[r-1][c] + S[r-1][c-1] - S[r-2][c-1]
    //
    // This recurrence gives triangular prefix sums.

    vector<vector<int>> A(N + 3, vector<int>(N + 3, 0));
    vector<vector<int>> B(N + 3, vector<int>(N + 3, 0));

    for (int k = 0; k < M; ++k) {
        int a, b, x;
        cin >> a >> b >> x;

        // Add +1 to triangle with top (a,b), height x
        A[a][b] += 1;
        A[a + x + 1][b] -= 1;

        // Subtract the shifted part to limit right boundary
        B[a][b + 1] += 1;
        B[a + x + 1][b + x + 2] -= 1;
    }

    auto build = [&](vector<vector<int>>& D) {
        vector<vector<int>> S(N + 3, vector<int>(N + 3, 0));
        for (int r = 1; r <= N; ++r) {
            for (int c = 1; c <= r; ++c) {
                S[r][c] = D[r][c];
                if (r - 1 >= 1) S[r][c] += S[r - 1][c];
                if (r - 1 >= 1 && c - 1 >= 1) S[r][c] += S[r - 1][c - 1];
                if (r - 2 >= 1 && c - 1 >= 1) S[r][c] -= S[r - 2][c - 1];
            }
        }
        return S;
    };

    auto SA = build(A);
    auto SB = build(B);

    long long ans = 0;
    for (int r = 1; r <= N; ++r) {
        for (int c = 1; c <= r; ++c) {
            if (SA[r][c] - SB[r][c] > 0) ++ans;
        }
    }

    cout << ans << '\n';
    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());

        // Use a 2D BIT (Fenwick tree) for range updates and point queries
        // Coordinates: (row, col). We'll map (a,b) to 1-indexed BIT indices.
        int size = N + 2;
        int[][] bit = new int[size][size];

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            int x = Integer.parseInt(st.nextToken());
            // Vertices: (a,b), (a+x, b), (a+x, b+x)
            // All points inside this triangle (including boundary) are enclosed.
            // We'll add +1 to all points inside the triangle.
            // Using difference array technique on 2D BIT:
            // For each row r from a to a+x, the column range is [b, b + (r - a)]
            // We'll update range [b, b + (r - a)] for each row r.
            // To do efficiently, we can update using 2D difference:
            // For a triangle, we can do:
            // add(r1, c1, +1)
            // add(r1, c2+1, -1)
            // add(r2+1, c1, -1)
            // add(r2+1, c2+1, +1)
            // But here the right bound changes with row, so we need per-row updates.
            // Since N ≤ 2000, M ≤ 100000, we can do per-row updates with prefix sums.
            // We'll use a 2D difference array diff[N+2][N+2] and then compute prefix sums.
            // This is simpler and fast enough.
            int r1 = a, r2 = a + x;
            for (int r = r1; r <= r2; r++) {
                int c1 = b;
                int c2 = b + (r - a);
                // update diff[r][c1] += 1; diff[r][c2+1] -= 1;
                bit[r][c1] += 1;
                if (c2 + 1 <= N) {
                    bit[r][c2 + 1] -= 1;
                }
            }
        }

        // Now compute prefix sums per row to get actual counts
        int count = 0;
        for (int r = 1; r <= N; r++) {
            int cur = 0;
            for (int c = 1; c <= r; c++) {
                cur += bit[r][c];
                if (cur > 0) {
                    count++;
                }
            }
        }

        System.out.println(count);
    }
}

