        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());

        boolean[][] covered = new boolean[N + 1][N + 1];

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            int x = Integer.parseInt(st.nextToken());

            for (int r = a; r <= a + x; r++) {
                int maxC = b + (r - a);
                for (int c = b; c <= maxC; c++) {
                    covered[r][c] = true;
                }
            }
        }

        int count = 0;
        for (int r = 1; r <= N; r++)
            for (int c = 1; c <= r; c++)
                if (covered[r][c]) count++;

        System.out.println(count);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();

        // We use coordinates:
        // u = b
        // v = a - b + 1
        // Then nails are 1 <= u, v and u + v <= N + 1.
        //
        // A triangle (a,b,x) contains exactly the nails satisfying:
        // u >= b, v >= a-b+1, u+v <= a+x+1
        //
        // So each rubber band corresponds to intersection of 3 half-planes.
        // We count union over the triangular lattice using 3D imos on transformed coordinates.
        //
        // Let w = N + 2 - (u+v), so w >= 1 and u+v+w = N+2.
        // A triangle becomes:
        // u >= U0, v >= V0, w >= W0
        // where U0=b, V0=a-b+1, W0=N-a-x+1
        //
        // For fixed nail (u,v,w), it is covered iff there exists a triangle with
        // U0<=u, V0<=v, W0<=w.
        //
        // Thus we can mark points (U0,V0,W0) and compute 3D prefix sums over the simplex
        // 1<=u,v,w and u+v+w=N+2.

        int S = N + 2;

        // 3D array flattened: dimensions [S+1][S+1][S+1] would be too large if N big.
        // But valid region is only for u+v+w=S. We can instead do 2D prefix on (u,v),
        // because w is determined by u+v.
        //
        // Triangle condition:
        // b <= u
        // a-b+1 <= v
        // a+x+1 >= u+v  <=> N-a-x+1 <= N+2-(u+v) = w
        //
        // For each band, define:
        // U0 = b
        // V0 = a-b+1
        // T0 = a+x+1
        //
        // A nail (u,v) with u>=U0, v>=V0, u+v<=T0 is covered.
        //
        // We need union of such "upper-left rectangles cut by diagonal" over triangular grid.
        //
        // Use inclusion on rows by diagonal threshold:
        // For each triangle, for every sum s=u+v <= T0, all points with u>=U0, v>=V0 on that diagonal are covered.
        // Better approach: 2D imos on (u,v) triangular grid:
        // add +1 to region u>=U0, v>=V0, u+v<=T0.
        //
        // This can be done with 3-directional prefix on triangular lattice:
        // If diff marks at (U0,V0)+=1, (T0-V0+2,V0)-=1, (U0,T0-U0+2)-=1 in suitable transformed system...
        //
        // Simpler robust method:
        // Sweep by s = u+v. For each triangle active for s in [U0+V0, T0], on diagonal s
        // covered u range is [U0, s-V0].
        // Do event sweep over diagonals.

        @SuppressWarnings("unchecked")
        ArrayList<int[]>[] addAt = new ArrayList[S + 2];
        @SuppressWarnings("unchecked")
        ArrayList<int[]>[] removeAt = new ArrayList[S + 2];
        for (int i = 0; i <= S + 1; i++) {
            addAt[i] = new ArrayList<>();
            removeAt[i] = new ArrayList<>();
        }

        for (int i = 0; i < M; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            int x = fs.nextInt();

            int U0 = b;
            int V0 = a - b + 1;
            int start = a + 1;     // U0 + V0
            int end = a + x + 1;   // T0

            // On diagonal s, interval of u is [U0, s-V0]
            // left endpoint constant U0
            // right endpoint = s - V0, grows by 1 each step
            addAt[start].add(new int[]{U0, V0});
            if (end + 1 <= S) removeAt[end + 1].add(new int[]{U0, V0});
        }

        // On each diagonal s (2..N+1), valid u are 1..s-1.
        // Need union length of active intervals [L, R] where
        // L = U0, R = s - V0.
        //
        // Maintain difference counts over u positions for current diagonal.
        // Since active intervals' R increase by 1 every step, we can update efficiently:
        // When a triangle becomes active at diagonal s0, it contributes +1 to all diagonals >=s0:
        // current interval [U0, s-V0].
        // Moving from s to s+1 extends each active interval by +1 on right.
        //
        // We maintain:
        // baseDiff for currently active constant left starts
        // and count of active triangles by V0 to account for right extension.
        //
        // Easier and still efficient enough for moderate N:
        // Use Fenwick range add / point query on each diagonal with event intervals.
        // For each diagonal, process active triangles and generate intervals directly is too slow.
        //
        // Better:
        // For a triangle active from s=start..end:
        // On diagonal start, add interval [U0, start-V0] = [U0,U0].
        // Each next diagonal extends right by 1.
        // This is equivalent to adding 1 to all cells (u,v) with u>=U0, v>=V0.
        // So we can just do 2D suffix-add and then restrict to valid nails.
        //
        // 2D imos on square [1..N][1..N]:
        // add +1 to rectangle [U0..N] x [V0..N]
        // but a nail exists only if u+v<=N+1, and triangle additionally requires u+v<=T0.
        // Need subtract those beyond T0. So not enough.

        // Since constraints are not shown, use O((N+M) log^2 N)? hard.
        // We proceed with sweep using segment tree over u on each diagonal,
        // representing active intervals exactly. To avoid iterating active triangles,
        // use event lines in transformed coordinates:
        //
        // For fixed s, interval [U0, s-V0].
        // Add +1 on [U0, N], and add -1 on [s-V0+1, N].
        // For active triangles, first part depends only on U0, second on V0.
        //
        // Thus on diagonal s:
        // coverageCount(u) = (#active with U0<=u) - (#active with V0<=s-u)
        // second term should count active with R < u, i.e. s-V0 < u => V0 > s-u.
        // So covered if activePrefixU(u) - activeBad(u) > 0.
        //
        // We can compute exact count per u by:
        // count(u) = activeByU.prefix(u) - activeByV.suffix(s-u+1)
        // because active triangles with U0<=u and V0<=s-u.
        // Need count of active triangles satisfying both, not separate counts. So impossible independently.

        // Therefore fallback to direct interval union with active set.
        // If constraints are large, official solution is more advanced, but without them we choose
        // a practical balanced approach using active intervals and sorting/merging per diagonal.

        ArrayList<int[]> active = new ArrayList<>();
        long answer = 0;

        for (int s = 2; s <= N + 1; s++) {
            if (!addAt[s].isEmpty()) active.addAll(addAt[s]);

            if (!active.isEmpty()) {
                ArrayList<int[]> intervals = new ArrayList<>(active.size());
                for (int[] tr : active) {
                    int U0 = tr[0];
                    int V0 = tr[1];
                    int R = s - V0;
                    if (R >= U0) {
                        int L = U0;
                        if (L < 1) L = 1;
                        int maxU = s - 1;
                        if (R > maxU) R = maxU;
                        if (L <= R) intervals.add(new int[]{L, R});
                    }
                }

                if (!intervals.isEmpty()) {
                    intervals.sort(Comparator.comparingInt(a -> a[0]));
                    int curL = intervals.get(0)[0];
                    int curR = intervals.get(0)[1];
                    long covered = 0;
                    for (int i = 1; i < intervals.size(); i++) {
                        int l = intervals.get(i)[0];
                        int r = intervals.get(i)[1];
                        if (l <= curR + 1) {
                            if (r > curR) curR = r;
                        } else {
                            covered += curR - curL + 1L;
                            curL = l;
                            curR = r;
                        }
                    }
                    covered += curR - curL + 1L;
                    answer += covered;
                }
            }

            if (!removeAt[s + 1 > S ? S + 1 : s + 1].isEmpty()) {
                // no-op, handled below
            }

            if (!removeAt[s + 1 <= S ? s + 1 : 0].isEmpty()) {
                // no-op
            }

            if (s + 1 <= S && !removeAt[s + 1].isEmpty()) {
                ArrayList<int[]> rem = removeAt[s + 1];
                if (!rem.isEmpty()) {
                    HashMap<Long, Integer> cnt = new HashMap<>();
                    for (int[] x : rem) {
                        long key = (((long) x[0]) << 32) ^ (x[1] & 0xffffffffL);
                        cnt.put(key, cnt.getOrDefault(key, 0) + 1);
                    }
                    ArrayList<int[]> next = new ArrayList<>(Math.max(0, active.size() - rem.size()));
                    for (int[] x : active) {
                        long key = (((long) x[0]) << 32) ^ (x[1] & 0xffffffffL);
                        Integer c = cnt.get(key);
                        if (c == null || c == 0) {
                            next.add(x);
                        } else {
                            cnt.put(key, c - 1);
                        }
                    }
                    active = next;
                }
            }
        }

        System.out.println(answer);
    }
}
